import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import toast from 'react-hot-toast';
import styles from './Auth.module.css';

export default function Register() {
  const [form, setForm] = useState({ name: '', email: '', password: '', phone: '' });
  const [loading, setLoading] = useState(false);
  const { register } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      await register(form.name, form.email, form.password, form.phone);
      toast.success('Account created!');
      navigate('/');
    } catch (err) {
      toast.error(err.response?.data?.message || 'Registration failed');
    } finally {
      setLoading(false);
    }
  };

  const update = (field) => (e) => setForm({ ...form, [field]: e.target.value });

  return (
    <div className={styles.container}>
      <form className={styles.form} onSubmit={handleSubmit}>
        <h2>Create Account</h2>
        <input className={styles.input} placeholder="Full Name" value={form.name} onChange={update('name')} required />
        <input className={styles.input} type="email" placeholder="Email" value={form.email} onChange={update('email')} required />
        <input className={styles.input} type="password" placeholder="Password" value={form.password} onChange={update('password')} required />
        <input className={styles.input} placeholder="Phone (optional)" value={form.phone} onChange={update('phone')} />
        <button className={styles.btn} type="submit" disabled={loading}>
          {loading ? 'Creating...' : 'Sign Up'}
        </button>
        <p className={styles.link}>Already have an account? <Link to="/login">Login</Link></p>
      </form>
    </div>
  );
}
